Method.Source:
/// <summary>
/// pre build
/// </summary>
public void preBuild()
{
    super();
    dataContract    = this.dataContractObject();
    dialogFieldPrimaryRoute        = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmPrimaryRoute));
    dialogFieldRouteStop        = this.bindInfo().getDialogField(dataContract, methodstr(METSalesOrderShipmentWorkbenchRouteUpdateContract,parmRouteStop));
    dialogFieldPrimaryRoute.enabled(false);
    dialogFieldRouteStop.enabled(false);
}
